// Constructs a Compressed Sparse Row (CSR) representation from the
// paralog.tsv output generated by the clustering pipeline.
// Unlike the CSC representation, the CSR representation is grouped by mag_id (row) rather than family_id (column).
// paralog.tsv is written cluster by cluster, i.e. grouped by family_id, so the entries of one MAG are spread
// over the whole file. Building CSR therefore requires a sort-and-merge approach (external merge sort):
// Step 1: read the input in bounded chunks ("runs") and sort each chunk in memory by (mag_id, family_id) and write to a temporary file
// Step 2: merge the sorted runs into the output CSR representation, writing the indptr, indices, and data files in a single pass
// Memory is bounded by the sort buffer of step 1 (entries_per_run x 10 bytes) plus one read buffer per run in step 2,
// never by the size of the input. Note: the step-1 buffer is not freed before step 2, so both add up.
//
// The resulting matrix is written as three binary files
//   indptr  : row pointer array (u64)
//   indices : column indices of non-zero entries (u32 family_id)
//   data    : copy number of each non-zero entry (u16; the run aborts if a value exceeds 65535)
// The binary format is chosen to allow direct memory mapping
// (e.g. via numpy.memmap) without requiring an additional conversion step.


// Imports
use std::cmp::Ordering;
use std::collections::BinaryHeap;
use std::convert::TryInto;
use std::env;
use std::fs::{self, File};
use std::io::{self, BufRead, BufReader, BufWriter, Read, Write};
use std::path::PathBuf;

// Buffer sizes in MiB, overridable via MAGRIX_READ_BUF_MB / MAGRIX_WRITE_BUF_MB / MAGRIX_MERGE_BUF_MB
// 8 MiB each: no measurable speed difference between 1 and 256 MiB in the buffer sweep (results/).
const DEFAULT_READ_BUF_MB: usize = 8;
const DEFAULT_WRITE_BUF_MB: usize = 8;
const DEFAULT_MERGE_BUF_MB: usize = 4; // per-run read buffer during the merge
const DEFAULT_ROWS_PER_RUN: usize = 20_000_000; // ~240MB sort buffer in Phase 1

// Buffer size in bytes: the environment variable `var` (in MiB) if set, else the default.
fn buffer_size(var: &str, default_mb: usize) -> usize {
    let mb = match env::var(var) {
        Ok(v) => v.parse::<usize>().ok().filter(|&n| n > 0)
            .unwrap_or_else(|| panic!("{} must be a positive integer (MiB), got {:?}", var, v)),
        Err(_) => default_mb,
    };
    mb * 1024 * 1024
}

// One pending entry per run is kept in memory during the merge (step 2).
// run_idx remembers which run the entry came from, so the next entry can be read from that same run.
struct HeapItem {
    mag_id: u32,
    family_id: u32,
    value: u16,
    run_idx: usize,
}

// Size of one (mag_id, family_id, value) record in a run file: u32 + u32 + u16
const RECORD_BYTES: usize = 10;

// Copy numbers are stored as u16. Abort instead of silently truncating if one doesn't fit.
fn to_u16(value: u32) -> u16 {
    u16::try_from(value).unwrap_or_else(|_| panic!("copy number {} exceeds u16 range (max 65535)", value))
}

// Ordering is based on the matrix position (mag_id first, then family_id), not on the value
impl PartialEq for HeapItem {
    fn eq(&self, other: &Self) -> bool {
        (self.mag_id, self.family_id) == (other.mag_id, other.family_id)
    }
}
impl Eq for HeapItem {}

impl PartialOrd for HeapItem {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
impl Ord for HeapItem {
    // Reverse the comparison so that the BinaryHeap behaves as a min-heap
    fn cmp(&self, other: &Self) -> Ordering {
        (other.mag_id, other.family_id).cmp(&(self.mag_id, self.family_id))
    }
}

// Read one (mag_id, family_id, value) record from a binary run; Ok(None) at the end of the run
fn read_triple(r: &mut BufReader<File>) -> io::Result<Option<(u32, u32, u16)>> {
    let mut buf = [0u8; RECORD_BYTES];
    match r.read_exact(&mut buf) {
        Ok(()) => Ok(Some((
            u32::from_le_bytes(buf[0..4].try_into().unwrap()),
            u32::from_le_bytes(buf[4..8].try_into().unwrap()),
            u16::from_le_bytes(buf[8..10].try_into().unwrap()),
        ))),
        Err(e) if e.kind() == io::ErrorKind::UnexpectedEof => Ok(None),
        Err(e) => Err(e),
    }
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 4 {
        eprintln!("Usage: build_csr <paralog.tsv> <num_mags> <out_prefix> [entries_per_run]");
        std::process::exit(1);
    }
    let tsv_path = &args[1];
    // Needed to write indptr entries for MAGs without any entry at the end
    let num_mags: u32 = args[2].parse().expect("num_mags must be an integer");
    let out_prefix = &args[3];
    // Optional 4th argument: how many entries are sorted in memory per run (trade-off: fewer, larger runs
    // need a bigger sort buffer; more, smaller runs need more merge buffers in step 2)
    let entries_per_run: usize = args
        .get(4)
        .map(|s| s.parse().expect("entries_per_run must be an integer"))
        .unwrap_or(DEFAULT_ROWS_PER_RUN);

    let read_buf = buffer_size("MAGRIX_READ_BUF_MB", DEFAULT_READ_BUF_MB);
    let write_buf = buffer_size("MAGRIX_WRITE_BUF_MB", DEFAULT_WRITE_BUF_MB);
    let merge_buf = buffer_size("MAGRIX_MERGE_BUF_MB", DEFAULT_MERGE_BUF_MB);
    eprintln!(
        "Buffers: read={} MiB write={} MiB merge={} MiB/run",
        read_buf >> 20, write_buf >> 20, merge_buf >> 20
    );

    // Temporary directory for the sorted runs, deleted after the merge
    let run_dir = PathBuf::from(format!("{}.csr_runs", out_prefix));
    fs::create_dir_all(&run_dir)?;

    // ── Phase 1: run generation ──────────────────────────────────────────────
    eprintln!("Phase 1: generating sorted runs (entries_per_run={}) ...", entries_per_run);
    let infile = File::open(tsv_path)?;
    let reader = BufReader::with_capacity(read_buf, infile);

    // Sort buffer, allocated once at full size: entries_per_run x 10 bytes (u32 + u32 + u16)
    let mut buffer: Vec<(u32, u32, u16)> = Vec::with_capacity(entries_per_run);
    let mut run_paths: Vec<PathBuf> = Vec::new();
    let mut entries_read: u64 = 0;
    let mut max_value: u32 = 0; // diagnostic only: largest copy number, printed in the summary

    // Sort the buffer by matrix position and write it as one binary run file (10 bytes per entry, little-endian)
    let flush_run = |buffer: &mut Vec<(u32, u32, u16)>, run_paths: &mut Vec<PathBuf>, run_dir: &PathBuf| -> io::Result<()> {
        if buffer.is_empty() {
            return Ok(());
        }
        buffer.sort_unstable_by_key(|&(mag, fam, _)| (mag, fam));
        let path = run_dir.join(format!("run_{}.bin", run_paths.len()));
        let mut w = BufWriter::with_capacity(write_buf, File::create(&path)?);
        for &(mag, fam, val) in buffer.iter() {
            w.write_all(&mag.to_le_bytes())?;
            w.write_all(&fam.to_le_bytes())?;
            w.write_all(&val.to_le_bytes())?;
        }
        w.flush()?;
        run_paths.push(path);
        buffer.clear();
        Ok(())
    };

    // Read paralog.tsv (representative_gene, family_id, MAG, paralog_count) and fill the buffer;
    // whenever it is full, sort it and write it out as the next run
    for line in reader.lines() {
        let line = line?;
        // Skip empty lines and the header line
        if line.is_empty() || line.starts_with("representative_gene") {
            continue;
        }
        let mut parts = line.split('\t');
        let _rep = parts.next().unwrap(); // not needed, family_id identifies the column
        let family_id: u32 = parts.next().unwrap().parse().expect("bad family_id");
        let mag_id: u32 = parts.next().unwrap().parse().expect("bad mag_id");
        let value: u32 = parts.next().unwrap().parse().expect("bad value");
        entries_read += 1;
        if value > max_value {
            max_value = value;
        }

        buffer.push((mag_id, family_id, to_u16(value)));
        if buffer.len() >= entries_per_run {
            flush_run(&mut buffer, &mut run_paths, &run_dir)?;
            eprintln!("  run {} written ({} entries read so far)", run_paths.len(), entries_read);
        }
    }
    // Write the last, partly filled buffer as the final run
    flush_run(&mut buffer, &mut run_paths, &run_dir)?;
    eprintln!("Phase 1 done: {} entries in {} runs", entries_read, run_paths.len());

    // ── Phase 2: k-way merge ─────────────────────────────────────────────────
    eprintln!("Phase 2: merging {} runs ...", run_paths.len());
    // All runs are open at the same time, each with its own read buffer of merge_buf bytes
    let mut readers: Vec<BufReader<File>> = run_paths
        .iter()
        .map(|p| BufReader::with_capacity(merge_buf, File::open(p).unwrap()))
        .collect();

    let mut indptr_w = BufWriter::with_capacity(write_buf, File::create(format!("{}.csr.indptr", out_prefix))?);
    let mut indices_w = BufWriter::with_capacity(write_buf, File::create(format!("{}.csr.indices", out_prefix))?);
    let mut data_w = BufWriter::with_capacity(write_buf, File::create(format!("{}.csr.data", out_prefix))?);

    // Seed the heap with one element per run (its smallest, since each run file
    // is individually sorted). Each pop() then yields the smallest (mag_id,
    // family_id) across ALL runs; pushing that run's next element right after
    // keeps exactly one pending element per run in the heap at all times — this
    // is what bounds Phase 2 memory to O(number of runs) instead of O(nnz).
    let mut heap: BinaryHeap<HeapItem> = BinaryHeap::new();
    for (i, r) in readers.iter_mut().enumerate() {
        if let Some((mag, fam, val)) = read_triple(r)? {
            heap.push(HeapItem { mag_id: mag, family_id: fam, value: val, run_idx: i });
        }
    }

    let mut current_mag: Option<u32> = None; // MAG of the entries currently being written
    let mut next_indptr_mag: u32 = 0; // next MAG whose indptr entry still has to be written
    let mut cum_offset: u64 = 0; // entries written to indices/data so far, used to fill indptr

    // The heap returns the entries in global (mag_id, family_id) order, so the CSR arrays can be
    // written front to back. indptr is filled exactly like in build_csc, just per MAG instead of per family.
    while let Some(item) = heap.pop() {
        if current_mag != Some(item.mag_id) {
            // Safety check: a new MAG must never be smaller than the previous one
            assert!(item.mag_id >= current_mag.unwrap_or(0), "merge produced out-of-order mag_id");
            // Write indptr entries up to this MAG; MAGs without entries get the same offset (empty row)
            while next_indptr_mag <= item.mag_id {
                indptr_w.write_all(&cum_offset.to_le_bytes())?;
                next_indptr_mag += 1;
            }
            current_mag = Some(item.mag_id);
        }
        indices_w.write_all(&item.family_id.to_le_bytes())?;
        data_w.write_all(&item.value.to_le_bytes())?;
        cum_offset += 1;

        // Refill the heap with the next entry of the run the popped entry came from
        if let Some((mag, fam, val)) = read_triple(&mut readers[item.run_idx])? {
            heap.push(HeapItem { mag_id: mag, family_id: fam, value: val, run_idx: item.run_idx });
        }
    }

    // Final indptr entry for the last MAG, and fill in any MAGs without entries after it
    while next_indptr_mag <= num_mags {
        indptr_w.write_all(&cum_offset.to_le_bytes())?;
        next_indptr_mag += 1;
    }

    indptr_w.flush()?;
    indices_w.flush()?;
    data_w.flush()?;

    // Temp runs are pure intermediate scratch — safe to remove now that the merge succeeded.
    fs::remove_dir_all(&run_dir)?;

    eprintln!("CSR done. nnz={} num_mags={} max_value={}", cum_offset, num_mags, max_value);
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn item(mag_id: u32, family_id: u32) -> HeapItem {
        HeapItem { mag_id, family_id, value: 0, run_idx: 0 }
    }

    #[test]
    fn heap_pops_smallest_mag_id_first() {
        // std BinaryHeap is a max-heap; Ord is deliberately reversed on
        // HeapItem so it behaves as a min-heap here -- this is exactly the
        // property Phase 2's k-way merge depends on to emit CSR rows in
        // ascending mag_id order.
        let mut heap: BinaryHeap<HeapItem> = BinaryHeap::new();
        heap.push(item(5, 0));
        heap.push(item(1, 0));
        heap.push(item(3, 0));

        assert_eq!(heap.pop().unwrap().mag_id, 1);
        assert_eq!(heap.pop().unwrap().mag_id, 3);
        assert_eq!(heap.pop().unwrap().mag_id, 5);
    }

    #[test]
    fn heap_breaks_ties_on_family_id() {
        let mut heap: BinaryHeap<HeapItem> = BinaryHeap::new();
        heap.push(item(1, 9));
        heap.push(item(1, 2));
        heap.push(item(1, 5));

        assert_eq!(heap.pop().unwrap().family_id, 2);
        assert_eq!(heap.pop().unwrap().family_id, 5);
        assert_eq!(heap.pop().unwrap().family_id, 9);
    }

    #[test]
    fn heap_orders_by_mag_id_before_family_id() {
        let mut heap: BinaryHeap<HeapItem> = BinaryHeap::new();
        heap.push(item(2, 0)); // higher mag_id but lowest family_id
        heap.push(item(1, 100));

        // mag_id must dominate the comparison even though family_id 0 < 100
        assert_eq!(heap.pop().unwrap().mag_id, 1);
    }
}
